// ═══ UNBOUNDED QUEUE: latency tail + OOM! ═══
ExecutorService BAD = Executors.newFixedThreadPool(10);
// Internally: new ThreadPoolExecutor(10, 10, 0, SECONDS, new LinkedBlockingQueue<>())
// LinkedBlockingQueue() → capacity = Integer.MAX_VALUE → UNBOUNDED!
// Under overload: 10 workers busy, tasks keep queuing...
// 1K tasks queued → 10K → 100K → 1M → OOM!
// Task submitted at 2:00 PM → processed at 2:30 PM (30 min latency!)
// Client: already timed out. Processing is WASTED work!

// ═══ BOUNDED QUEUE: predictable fail-fast! ═══
ThreadPoolExecutor GOOD = new ThreadPoolExecutor(
    10, 20, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(500),  // BOUNDED: max 500 queued!
    threadFactory,
    rejectionHandler  // fires when 20 workers + 500 queued = full!
);
// Overload: 521st task → REJECTED immediately!
// Client: gets 503 in 10ms → retries or shows error → NOT waiting 30 min!

// ═══ CUSTOM RejectedExecutionHandler ═══
RejectedExecutionHandler customHandler = (runnable, executor) -> {
    // 1. METRICS: increment rejection counter!
    rejectionCounter.increment();  // Prometheus/Micrometer!

    // 2. LOG: queue depth for debugging!
    log.warn("Task rejected! Queue: {}/{}, Active: {}/{}",
        executor.getQueue().size(), 500,
        executor.getActiveCount(), executor.getMaximumPoolSize());

    // 3. ALERT: if rejection rate > threshold!
    if (rejectionCounter.count() > 100) alertOps("Pool saturated!");

    // 4. FALLBACK: CallerRuns as back-pressure!
    if (!executor.isShutdown()) {
        runnable.run();  // caller thread executes → natural throttle!
    }
};

// ═══ WHEN TO USE EACH BUILT-IN POLICY ═══
// AbortPolicy:        task loss UNACCEPTABLE, caller handles exception
// CallerRunsPolicy:   natural back-pressure, slow producer down
// DiscardPolicy:      NEVER in production (silent loss!)
// DiscardOldestPolicy: latest > oldest (real-time dashboards only)
// Custom:             ALWAYS in production (metrics + logging + fallback!)
