package com.bank.queuereject;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class QueueVsRejectTest {

    // ═══ Unbounded queue: tasks pile up ═══
    @Test
    void unboundedQueue_tasksPileUp() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(1);  // unbounded queue!
        for (int i = 0; i < 1000; i++) {
            pool.submit(() -> {
                try { Thread.sleep(100); } catch (InterruptedException e) { }
            });
        }
        // 1 worker × 100ms each = 100 seconds to clear 1000 tasks!
        // Queue: ~999 tasks waiting! In production: millions → OOM!
        ThreadPoolExecutor tpe = (ThreadPoolExecutor) pool;
        System.out.println("Queued: " + tpe.getQueue().size());  // ~999!
        pool.shutdownNow();
    }

    // ═══ Bounded queue + rejection: predictable! ═══
    @Test
    void boundedQueue_predictableRejection() {
        AtomicInteger rejected = new AtomicInteger(0);
        AtomicInteger completed = new AtomicInteger(0);

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 4, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(5),
            Executors.defaultThreadFactory(),
            (r, e) -> rejected.incrementAndGet()  // count rejections!
        );

        for (int i = 0; i < 50; i++) {
            pool.submit(() -> {
                try { Thread.sleep(200); } catch (InterruptedException e) { }
                completed.incrementAndGet();
            });
        }

        System.out.println("Rejected immediately: " + rejected.get());
        assertThat(rejected.get()).isGreaterThan(0);  // some rejected! Fast fail!

        pool.shutdown();
        try { pool.awaitTermination(30, TimeUnit.SECONDS); } catch (InterruptedException e) { }
    }

    // ═══ Custom handler: metrics + CallerRuns fallback ═══
    @Test
    void customHandler_metricsAndFallback() throws InterruptedException {
        AtomicInteger rejections = new AtomicInteger(0);
        AtomicInteger callerRan = new AtomicInteger(0);

        RejectedExecutionHandler customHandler = (r, executor) -> {
            rejections.incrementAndGet();  // metric!
            if (!executor.isShutdown()) {
                r.run();  // CallerRuns fallback!
                callerRan.incrementAndGet();
            }
        };

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(2),
            Executors.defaultThreadFactory(),
            customHandler
        );

        // Fill: 1 worker + 2 queued = 3 tasks
        for (int i = 0; i < 3; i++) {
            pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) { } });
        }

        // 4th task: REJECTED → custom handler → caller runs!
        pool.submit(() -> {});

        Thread.sleep(100);
        System.out.println("Rejections: " + rejections.get() + ", CallerRan: " + callerRan.get());

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }

    // ═══ Queue depth monitoring ═══
    @Test
    void queueDepthMonitoring() throws InterruptedException {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 2, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(100));

        for (int i = 0; i < 20; i++) {
            pool.submit(() -> { try { Thread.sleep(200); } catch (InterruptedException e) { } });
        }
        Thread.sleep(50);

        System.out.println("Queue depth: " + pool.getQueue().size());  // monitoring!
        System.out.println("Active: " + pool.getActiveCount());
        System.out.println("Completed: " + pool.getCompletedTaskCount());
        // Expose these as Prometheus gauges!

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }
}
